import init,{WasmEmulator} from './esp32/pkg/esp_emu.js';
import {ESP_BOARDS,validateESPImage} from './esp-boards.js';
import {ESPCircuitRuntime} from './esp-circuit-runtime.js';
export class ESPRuntime {
 static initialize(bytes){return this.initialization??=init(bytes?{module_or_path:bytes}:undefined).catch(error=>{this.initialization=null;throw error;});}
 constructor(image,{chip='esp32c3',bootFromROM=false,inputs={}}={}){validateESPImage(image,chip,{bootFromROM});this.chip=chip;this.board=ESP_BOARDS[chip];this.emulator=new WasmEmulator(this.board.target||chip);try{this.emulator.load_default_rom();this.emulator.set_boot_from_rom(bootFromROM);this.emulator.load_firmware(new Uint8Array(image));this.inputs={};for(const pin of this.board.gpio)this.setInput(pin,inputs[pin]??true);}catch(error){this.emulator.free();throw error;}}
 setInput(pin,high){if(this.circuit)throw Error('GPIO girişini devre bağlantıları belirler.');if(!this.board.gpio.includes(+pin))throw Error('Kart üzerinde bu GPIO yok.');this.inputs[pin]=!!high;this.emulator.gpio_set_input(+pin,!!high);}
 queueSerial(text){if(typeof text!=='string'||text.length>4096)throw Error('UART mesaj sınırı 4096 karakter.');this.emulator.uart_input(new TextEncoder().encode(text));}
 attachCircuit(project){this.circuit=new ESPCircuitRuntime(this,project);}
 step(instructions=100000){if(!Number.isInteger(instructions)||instructions<1||instructions>1000000)throw Error('Adım sınırı geçersiz.');return this.circuit?this.circuit.step(instructions):this.emulator.run_batch(instructions);}
 snapshot(){const emu=this.emulator,gpio=Array.from(emu.gpio_state());this.circuit?.refresh(true);return{chip:this.chip,cycles:emu.cycles(),time:emu.cycles()/(emu.cycles_per_us()*1000000),hz:emu.cycles_per_us()*1000000,pc:emu.pc(),pcs:Array.from({length:emu.num_harts()},(_,h)=>emu.hart_pc(h)),registers:Array.from(emu.registers()),pins:this.board.gpio.map(pin=>{const bank=pin<32?0:1,mask=1<<(pin%32),output=!!(gpio[bank+2]&mask),high=this.circuit?this.inputs[pin]:output?!!(gpio[bank]&mask):this.inputs[pin],dc=this.circuit?.solution,voltage=dc?dc.voltages.get(dc.netlist.net(this.circuit.board.id+':GPIO'+pin)):high?3.3:0;return{pin,output,high,voltage:Number.isFinite(voltage)?voltage:null};}),gpio};}
 reset(){const before=this.circuit,cycle=before?.cycle()||0,eeprom=before?.devices.filter(d=>d.type==='eeprom').map(d=>{const c=d.controller;c.tick(cycle);return{id:d.id,memory:c.memory.slice(),pointer:c.pointer,revision:c.revision,committing:c.committing?new Map(c.committing):null,busyUntil:Math.max(0,c.busyUntil-cycle)};})||[];this.emulator.restart();for(const[pin,high]of Object.entries(this.inputs))this.emulator.gpio_set_input(+pin,high);if(before){this.circuit=new ESPCircuitRuntime(this,before.project);for(const saved of eeprom){const c=this.circuit.controllers.get(saved.id)?.controller;if(c){const {id,...state}=saved;Object.assign(c,state);}}this.circuit.refresh(true);}}
 readMemory(address,length=128){if(!Number.isInteger(address)||address<0||address>0xffffffff||!Number.isInteger(length)||length<1||length>4096||address+length>0x100000000)throw Error('Bellek adresi/boyutu geçersiz.');return this.emulator.read_memory(address,length);}
 dispose(){this.emulator.free();}
}
